contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address callee, bytes memory data) public {
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // c.forward forwards a low-level call to callee with data.
        // We can only observe whether it reverts via the try/catch above.
        // The rule is: forward reverts iff the low-level call to callee fails.
        // Since we cannot directly simulate callee.call(data) without side effects,
        // we use the fact that a call with empty data to an EOA (no code) succeeds,
        // while a call with non-empty data to an EOA (no code) fails.
        // Additionally, by the contract's semantics, if the callee is not a contract
        // and data is non-empty, the low-level call returns success=false, so forward must revert.
        bool expectRevert;
        if (callee.code.length == 0) {
            expectRevert = data.length > 0;
        } else {
            // For contracts, we cannot predict without executing; but a successful
            // low-level call to a contract with no return data will not revert.
            // We cannot determine in general, so we only assert the direction we can:
            // If forward did NOT revert, then the low-level call must have succeeded,
            // which requires that either callee has code or data is empty (for EOAs).
            expectRevert = false;
        }

        // General rule: forward succeeds only if the low-level call to callee succeeds.
        // In particular, a call to an address with no code and non-empty data must revert.
        // We assert: if callee has no code, then forward reverts exactly when data is non-empty.
        assert(callee.code.length > 0 || reverted == (data.length > 0));
    }

    receive() external payable {}
}

