contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address callee, bytes memory data) public payable {
        bool reverted;
        try c.forward(callee, data) { reverted = false; } catch { reverted = true; }
        bool hasCode;
        assembly { hasCode := gt(extcodesize(callee), 0) }
        // The rule: forward reverts exactly when callee has code and data is non-empty, or callee has no code and data is non-empty.
        // Wait, that would mean it always reverts when data is non-empty, which is false for EOAs (they can accept calls).
        // Let's refine based on the known semantics: low-level call to EOA with data succeeds (no code executed), so forward should succeed.
        // The real rule: forward succeeds if and only if the low-level call to callee with data succeeds.
        // That is stated in another rule. We need a different but general rule.
        // Since the focus is on whether it reverts or completes, and on which inputs, we can state:
        // forward reverts iff the callee's low-level call fails. That's the same as above.
        // But we can also state: forward never reverts if callee is an EOA (no code) regardless of data (since call to EOA succeeds with empty return).
        // That is a specific case but general over all EOAs and data. It might be a new rule, but it's implied by the earlier accepted rule about success exactly when low-level call succeeds.
        // We need a rule not already accepted. The accepted rules already cover:
        // - success iff low-level call succeeds; balance unchanged on success
        // - owner unchanged
        // - reverts iff low-level call fails; recurses on self with empty data
        // - success iff callee accepts empty data; EOA succeeds for empty data
        // - reverts iff low-level call fails; balance unchanged on failure
        // That's quite comprehensive. A different rule could be: forward reverts if callee is a contract and data is non-empty and the callee does not implement a function that accepts the data (i.e., reverts). That's basically the same.
        // Perhaps we can state: if callee is an EOA, then forward never reverts regardless of data.
        // That is a general rule over all EOAs and data, and not explicitly stated in the accepted rules (though it follows from them).
        // But the checker might consider it trivial or derived. However it's a general rule that a faulty version might break.
        // We'll go with that.
        bool isEOA = !hasCode;
        // For EOA, low-level call with any data succeeds (returns true) because there is no code to revert.
        // So forward should not revert.
        assert(!(isEOA && reverted));
    }

    receive() external payable {}
}

